#!/usr/bin/env node
/**
 * Registers the Dutch cluster in data/articles.json.
 *
 * The eleven pages are generated by `generate-nl-cluster.mjs` from
 * `nl-cluster.data.mjs`; this script derives their listing metadata from the
 * same page objects, so the two can never drift apart. It writes only the `nl`
 * keys under `categories` and `articles` and leaves PT and EN untouched.
 *
 * Re-runnable: an existing `nl` array is replaced, not appended to.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PAGES } from './nl-cluster.data.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

// The cluster is one category with one landing, as briefed. Every page carries
// it: the hub is the landing for all of them, including itself.
const NL_CATEGORIES = [
  {
    slug: 'nl-verzekeringen',
    title: 'Verzekeringen Portugal',
    short: 'Verzekeringen',
    landing: '/nl/verzekeringen-portugal/',
    landingLabel: 'Verzekeringen in Portugal',
  },
];

// Gradients follow the tag, so the four themes stay visually distinct wherever
// the cards are rendered. No page in the cluster has a photograph yet.
const GRADIENT = {
  Zorg: 'linear-gradient(135deg, #111927 0%, #17243D 100%)',
  Auto: 'linear-gradient(135deg, #17243D 0%, #4B5A67 100%)',
  Wonen: 'linear-gradient(135deg, #6B4A2F 0%, #B8323E 100%)',
  Ondernemen: 'linear-gradient(135deg, #111927 0%, #B8323E 100%)',
  Overzicht: 'linear-gradient(135deg, #111927 0%, #B8323E 100%)',
};

const nl = PAGES.map((p) => ({
  slug: p.slug,
  lang: 'nl',
  status: 'published',
  url: p.url,
  category: 'nl-verzekeringen',
  tag: p.article.tag,
  title: p.h1,
  metaTitle: p.title,
  description: p.description,
  excerpt: p.article.excerpt,
  image: null,
  imageGradient: GRADIENT[p.article.tag] || GRADIENT.Overzicht,
  imageAlt: p.h1,
  published: p.published,
  modified: p.modified,
  dateLabel: p.article.dateLabel,
  readingTime: p.article.readingTime,
  featured: false,
  // `translationOf` pairs a PT article with its EN twin by slug and cannot
  // express what these pages declare: an equivalent that may live in either of
  // the other two languages, under an unrelated slug. The hreflang pairs are
  // recorded here in the form the pages themselves emit.
  translationOf: null,
  alternates: Object.keys(p.hreflang || {}).length ? p.hreflang : null,
}));

const path = join(ROOT, 'data', 'articles.json');
const data = JSON.parse(await readFile(path, 'utf8'));
data.categories.nl = NL_CATEGORIES;
data.articles.nl = nl;
await writeFile(path, JSON.stringify(data, null, 2) + '\n');

console.log(`nl registered: ${nl.length}`);
for (const a of nl) console.log(`  ${a.tag.padEnd(11)} ${a.url}${a.alternates ? '  ↔ ' + Object.values(a.alternates).join(', ') : ''}`);
